const $ = s => document.querySelector(s);
const escapeHTML = v => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e = escapeHTML;
let state={domains:[],scans:[],audit:[],running:[]}, auth, currentView='overview', search='';
let dashboardFilter={days:'7',accounts:'users'},refreshSequence=0;
let zapSearch='',zapSelectedId='',focusedScan=null,focusedCollection=null,collectionDialogType='';
const views={ad:['Active Directory','Eventos de autenticação, correlação de comportamento e revisão de alertas.'],internal:['Domínios internos','DNS, certificados e HTTPS dentro do escopo autorizado de cada coletor.'],aws:['AWS','Achados de segurança e inventário DNS por conta e região, com acesso somente de leitura.'],collectors:['Coletores','Conexão e escopo dos coletores corporativos e de VPC.'],zap:['ZAP','Análise passiva e testes autorizados de SQL injection, com fila e histórico.'],overview:['Visão geral','Um olhar sobre a segurança do seu patrimônio digital.'],domains:['Domínios','Inventário e acompanhamento dos ativos públicos da empresa.'],findings:['Achados','Evidências observadas e orientações para priorizar a correção.'],scans:['Verificações','Histórico, execução e agendamento dos controles de segurança.'],controls:['Cobertura de segurança','O que foi avaliado, o que precisa de validação e os próximos controles.'],integrations:['Integrações','Identidade corporativa, ferramentas de análise e expansão do monitoramento.'],audit:['Trilha de auditoria','Rastreabilidade das ações realizadas neste workspace.']};
const findingGroupsOpen=new Map();
const severity={critical:'Crítica',high:'Alta',medium:'Média',low:'Baixa',info:'Informativa'};
const statusName={partial:'Parcial',cancelled:'Cancelada',queued:'Na fila',completed:'Concluída',running:'Em execução',failed:'Falhou',interrupted:'Interrompida'};
const date=v=>v?new Date(v).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'—';
const quantity=(n,one,many)=>n+' '+(n===1?one:many);
const badge=(text,type='')=>`<span class="badge ${e(type)}">${e(text)}</span>`;
const empty=(title,text)=>`<div class="empty"><span class="empty-symbol">◎</span><strong>${e(title)}</strong><p>${e(text)}</p></div>`;
const latest=d=>d.latest_completed_scan||state.scans.find(s=>s.domain_id===d.id && s.status==='completed');
const latestAttempt=d=>d.latest_scan||state.scans.find(s=>s.domain_id===d.id);
const hostFindings=d=>[...(latest(d)?.result?.findings||[]),...(d.latest_zap||[]).flatMap(s=>(s.result?.findings||[]).map(f=>({...f,zapJob:s.id})))];
const descendants=d=>state.domains.filter(child=>child.hostname.endsWith('.'+d.hostname));
const dnsLabels={unknown:'DNS não consultado',public:'DNS público',private:'Privado / reservado',unresolved:'Sem DNS A/AAAA',error:'DNS inconclusivo'};
const pending=d=>['queued','running'].includes(latestAttempt(d)?.status);
const findings=()=>state.domains.flatMap(d=>hostFindings(d).map(f=>({...f,hostname:d.hostname,scanId:f.zapJob||latest(d)?.id})));
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,5000);}
async function api(path,body){const res=await fetch(path,{...(body!==undefined?{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':auth.user.csrf},body:JSON.stringify(body)}:{})});const data=await res.json();if(!res.ok)throw new Error(data.error||'Não foi possível concluir a operação.');return data;}
async function refresh(filter=dashboardFilter){const sequence=++refreshSequence;const next=await api('/api/overview?'+new URLSearchParams(filter));if(sequence!==refreshSequence)return;dashboardFilter={...filter};const changed=JSON.stringify(next)!==JSON.stringify(state);state=next;$('#nav-count').textContent=state.domains.length;$('#updated').textContent=date(new Date());if(changed||!$('#content').children.length)render();}
function scanBadge(d){
  const s=latestAttempt(d);
  if(!s)return badge('Não verificado');
  if(s.status!=='completed')return badge(statusName[s.status]||s.status,s.status);
  if(!s.result?.web)return badge('Inconclusiva','medium');
  return badge(s.result.findings?.length?'Com observações':'Concluída',s.result.findings?.length?'medium':'completed');
}
function domainTable(domains){
  return domains.length?`<div class="table-wrap"><table><thead><tr><th>DOMÍNIO / SUBDOMÍNIO</th><th>DNS</th><th>VARREDURA</th><th>ACHADOS</th><th>AGENDAMENTO</th><th>AÇÕES</th></tr></thead><tbody>${domains.map(d=>{
    const s=latest(d),attempt=latestAttempt(d),count=(s||d.latest_zap?.length)?hostFindings(d).length:undefined;
    return `<tr class="${d.parent_id?'subdomain-row':''}"><td><div class="domain-cell"><span class="domain-icon">${d.parent_id?'↳':'◎'}</span><div><strong>${e(d.hostname)}</strong><small>${d.parent_id?'Subdomínio':'Domínio principal'} · ${d.source==='crt.sh'?'Certificados públicos':'Cadastro manual'}</small></div></div></td><td>${badge(dnsLabels[d.dns_state]||dnsLabels.unknown,d.dns_state==='public'?'enabled':d.dns_state==='private'?'medium':'')}<small>${e(d.addresses?.slice(0,2).join(', ')||'—')}</small></td><td>${scanBadge(d)}<small>${date(attempt?.finished_at||attempt?.started_at)}${attempt?.result?.web?' · HTTP '+e(attempt.result.web.status):''}</small></td><td>${count!==undefined?badge(count+' observações',count?'medium':'completed'):badge('Não avaliado')}</td><td>${badge(d.enabled?'Ativo':'Pausado',d.enabled?'enabled':'')}<small>A cada ${e(d.interval_hours)}h</small></td><td><button class="small-btn" data-scan="${e(d.id)}" ${pending(d)?'disabled':''}>${pending(d)?statusName[attempt.status]:'Verificar'}</button><button class="small-btn" data-zap="${e(d.id)}" ${state.zap?.ready?'':'disabled'}>ZAP</button><button class="small-btn" data-schedule="${e(d.id)}">${d.enabled?'Pausar':'Agendar'}</button></td></tr>`;
  }).join('')}</tbody></table></div>`:empty('Seu inventário começa aqui','Adicione um domínio para acompanhar seus ativos.');
}
function domainGroups(){
  const term=search.toLowerCase();
  const roots=state.domains.filter(d=>!d.parent_id);
  const groups=roots.filter(d=>d.hostname.includes(term)||descendants(d).some(child=>child.hostname.includes(term)));
  return groups.length?groups.map(d=>{
    const children=descendants(d),visible=d.hostname.includes(term)?children:children.filter(child=>child.hostname.includes(term));
    const discovery=state.discoveries?.find(job=>job.domain_id===d.id);
    const discovering=['queued','running'].includes(discovery?.status);
    const note=!discovery?'Descubra os subdomínios presentes em certificados públicos.':discovering?'Buscando nomes e consultando DNS. A lista será atualizada automaticamente.':discovery.status==='completed'?`${discovery.result?.found||0} nomes encontrados · ${discovery.result?.added||0} novos · ${date(discovery.finished_at)}${discovery.result?.limited?' · Resultado limitado; até 100 nomes por descoberta.':''}`:'A descoberta não foi concluída. O inventário existente foi preservado; tente novamente depois.';
    return `<section class="panel domain-group"><div class="domain-group-header"><div><p class="eyebrow">DOMÍNIO PRINCIPAL</p><h2>${e(d.hostname)}</h2><p>${children.length} subdomínio(s) · ${[d,...children].filter(pending).length} varredura(s) na fila ou em execução</p></div><div class="domain-group-actions"><button class="secondary" data-discover="${e(d.id)}" ${discovering?'disabled':''}>${discovering?'Descobrindo…':'Descobrir subdomínios'}</button><button class="primary" data-scan-tree="${e(d.id)}">Verificar todos</button></div></div><div class="discovery-note">${badge(discovery?statusName[discovery.status]||discovery.status:'Descoberta pendente',discovery?.status||'')}<span>${e(note)}</span></div>${domainTable([d,...visible])}${!children.length?'<div class="panel-bottom">Nenhum subdomínio registrado. Certificados públicos não abrangem necessariamente todos os hosts.</div>':''}</section>`;
  }).join(''):empty('Nenhum domínio encontrado','Ajuste a busca ou cadastre um domínio.');
}
function overview(){
  const d=state.dashboard;if(!d)return empty('Carregando dashboard','Aguarde a consolidação dos dados.');
  const a=d.ad,r=d.range,n=value=>Number(value||0).toLocaleString('pt-BR'),short=value=>value?.split('-').reverse().join('/'),custom=!!dashboardFilter.start;
  const count=key=>(d.modules[key]||[]).reduce((total,v)=>total+v.count,0);
  const jobs=key=>(d.modules[key]||[]).map(v=>`${statusName[v.status]||v.status}: ${n(v.count)}`).join(' · ')||'Nenhuma execução no período';
  const module=(view,title,total,note,meta)=>`<button class="dash-module" data-view="${view}"><span>${title} <b>↗</b></span><strong>${n(total)}</strong><small>${note}</small><p>${e(meta)}</p></button>`;
  const sources=state.ad?.sources||[],live=sources.filter(s=>s.online&&s.status==='ok').length;
  const failureRate=a.totals.attempts?(a.totals.failures/a.totals.attempts*100).toLocaleString('pt-BR',{maximumFractionDigits:1}):'0';
  return `<section class="panel dash-filter-panel"><div><h2>Panorama de segurança</h2><p>${short(r.start)} a ${short(r.end)} · Horário de Brasília</p></div><form id="dashboard-filter"><label>Período<select name="days" id="dashboard-days">${[['1','Hoje'],['7','7 dias'],['15','15 dias'],['30','30 dias'],['custom','Personalizado']].map(([v,label])=>`<option value="${v}" ${(custom?'custom':String(dashboardFilter.days||7))===v?'selected':''}>${label}</option>`).join('')}</select></label><label>De<input type="date" name="start" value="${r.start}" ${custom?'':'disabled'} required></label><label>Até<input type="date" name="end" value="${r.end}" ${custom?'':'disabled'} required></label><label>Contas do AD<select name="accounts"><option value="users" ${r.accounts==='users'?'selected':''}>Usuários</option><option value="machines" ${r.accounts==='machines'?'selected':''}>Máquinas</option><option value="all" ${r.accounts==='all'?'selected':''}>Todas as contas</option></select></label><button class="primary" type="submit">Aplicar</button></form></section>
  <div class="dash-modules">${module('domains','Domínios públicos',state.domains.length,'Ativos no inventário atual',`${n(count('public'))} verificações no período · ${jobs('public')}`)}${module('zap','ZAP',count('zap'),'Execuções no período',`${state.zap?.ready?'Worker disponível':'Worker indisponível'} · ${jobs('zap')}`)}${module('internal','Rede interna',state.internalAssets?.length,'Hosts no inventário atual',`${n(count('internal'))} verificações no período · ${jobs('internal')}`)}${module('aws','AWS',state.awsConnections?.length,'Contas configuradas atualmente',`${n(count('aws'))} coletas no período · ${jobs('aws')}`)}</div>
  <div class="dash-section-title"><div><p class="eyebrow">ACTIVE DIRECTORY</p><h2>Autenticação e comportamento</h2></div><button class="text-action" data-view="ad">Abrir eventos e alertas →</button></div>
  <div class="stats dash-kpis">${[['Autenticações aceitas',a.totals.successes,`${n(a.totals.logons)} eventos de logon 4624`,'success'],['Falhas de autenticação',a.totals.failures,`${failureRate}% dos eventos de autenticação`,'failure'],['Contas observadas',a.totals.accounts,r.accounts==='users'?'Usuários; contas de máquina excluídas':r.accounts==='machines'?'Somente contas terminadas em $':'Usuários e contas de máquina',''],['Alertas no período',a.alertStats.total,`${n(a.alertStats.pending)} pendentes · ${n(a.alertStats.confirmed)} confirmados`,'alert']].map(([label,value,note,type])=>`<div class="stat ${type==='failure'?'alert':''}"><div class="stat-top">${label}</div><div class="stat-number dash-${type}">${n(value)}</div><small>${note}</small></div>`).join('')}</div>
  <div class="grid-two dash-activity-grid"><section class="panel"><div class="panel-header"><div><h2>Autenticações por dia</h2><p>Eventos aceitos e recusados no período selecionado</p></div>${badge(n(a.totals.attempts)+' eventos')}</div>${adDailyChart(a.series)}</section><section class="panel"><div class="panel-header"><h2>Saúde e cobertura da coleta</h2>${badge(`${live}/${sources.length} fontes`,live===sources.length&&live?'enabled':'medium')}</div><div class="dash-health">${sources.length?sources.map(s=>`<div><strong>${e(s.name)}</strong>${badge(!s.online?'Offline':adState[s.status]||s.status,s.online&&s.status==='ok'?'enabled':'medium')}<small>Última leitura: ${date(s.last_success)}${s.backlog?' · Processando fila de eventos':''}</small>${s.error?`<small>${e(adError[s.error]||s.error)}</small>`:''}</div>`).join(''):empty('Coletor AD não configurado','Configure uma fonte para receber eventos reais.')}<p>Dados disponíveis: ${date(a.coverage.firstEvent)} até ${date(a.coverage.lastEvent)}.</p><p>Contagem de eventos de logon, Kerberos e NTLM. Uma sessão pode gerar vários eventos. Retenção de até 30 dias e 200 mil eventos; dias sem dados aparecem zerados.</p></div></section></div>
  <div class="grid-two">${adRanking('Contas que mais autenticam',a.topSuccess,'success')}${adRanking('Contas com mais falhas',a.topFailures,'failure')}</div>
  <div class="grid-two"><section class="panel"><div class="panel-header"><div><h2>Alertas por comportamento</h2><p>Todos os tipos de conta · período selecionado</p></div>${badge(n(a.alertStats.falsePositive)+' falsos positivos')}</div>${a.alertsByRule.length?`<div class="dash-summary-list">${a.alertsByRule.map(v=>`<div><span>${e(v.title)}<small>${badge(severity[v.severity],v.severity)}</small></span><strong>${n(v.count)}</strong></div>`).join('')}</div>`:empty('Nenhum alerta neste período','A ausência de alertas não comprova ausência de comportamento suspeito.')}</section><section class="panel"><div class="panel-header"><div><h2>Origens com mais falhas</h2><p>IP ou estação informada pelo Windows</p></div></div>${a.origins.length?`<div class="dash-summary-list">${a.origins.map(v=>`<div><span>${e(v.origin)}<small>${n(v.accounts)} contas envolvidas</small></span><strong>${n(v.count)}</strong></div>`).join('')}</div>`:empty('Nenhuma origem com falhas','Eventos sem origem informada não entram neste ranking.')}</section></div>
  <section class="panel"><div class="panel-header"><h2>Distribuição dos eventos de autenticação</h2><span class="muted">Filtro de contas aplicado</span></div><div class="dash-event-types">${a.eventTypes.length?a.eventTypes.map(v=>`<div><strong>${n(v.count)}</strong><span>${e(({4624:'Logon aceito',4625:'Logon recusado',4768:'Kerberos · TGT',4769:'Kerberos · serviço',4771:'Falha Kerberos',4776:'Validação NTLM'})[v.eventId]||'Evento')}</span><small>ID ${v.eventId}</small></div>`).join(''):'<p class="muted">Nenhum evento de autenticação no período.</p>'}</div></section>`;
}

function adDailyChart(series){
  const max=Math.max(1,...series.flatMap(v=>[v.successes,v.failures])),n=v=>Number(v).toLocaleString('pt-BR');
  return `<div class="dash-daily"><div class="dash-legend"><span><i class="dash-dot accepted"></i>Aceitas</span><span><i class="dash-dot rejected"></i>Falhas</span><span>Máximo: ${n(max)}</span></div><div class="dash-chart-scroll"><div class="dash-chart">${series.map(v=>`<div class="dash-chart-day"><div class="dash-chart-pair" role="img" aria-label="${v.date}: ${n(v.successes)} aceitas e ${n(v.failures)} falhas" title="${v.date.split('-').reverse().join('/')}: ${n(v.successes)} aceitas · ${n(v.failures)} falhas"><span class="accepted" data-height="${v.successes/max*100}"></span><span class="rejected" data-height="${v.failures/max*100}"></span></div><small>${v.date.slice(8)}/${v.date.slice(5,7)}</small></div>`).join('')}</div></div><details class="dash-chart-data"><summary>Ver valores por dia</summary><div class="table-wrap"><table><thead><tr><th>DIA</th><th>ACEITAS</th><th>FALHAS</th></tr></thead><tbody>${series.map(v=>`<tr><td>${v.date.split('-').reverse().join('/')}</td><td>${n(v.successes)}</td><td>${n(v.failures)}</td></tr>`).join('')}</tbody></table></div></details></div>`;
}

function adRanking(title,rows,type){
  const max=Math.max(1,...rows.map(v=>v.count));
  return `<section class="panel"><div class="panel-header"><div><h2>${title}</h2><p>Top 10 · eventos registrados no período</p></div>${badge(type==='success'?'Aceitas':'Falhas',type==='success'?'enabled':'medium')}</div>${rows.length?`<ol class="dash-ranking">${rows.map((v,i)=>`<li><span class="dash-rank-position">${i+1}</span><div class="dash-rank-account"><div><strong title="${e(v.account)}">${e(v.account)}</strong><b>${Number(v.count).toLocaleString('pt-BR')}</b></div><div class="dash-rank-track"><span class="${type==='success'?'accepted':'rejected'}" data-width="${v.count/max*100}"></span></div><small>${v.origins} origens · Último evento: ${date(v.lastSeen)}</small></div></li>`).join('')}</ol>`:empty('Nenhuma conta neste período','Ajuste o intervalo ou o filtro de usuários e máquinas.')}</section>`;
}
function domainView(){return `<div class="panel"><div class="panel-header"><div><h2>Domínios e subdomínios</h2><p>${state.domains.filter(d=>!d.parent_id).length} domínios principais · ${state.domains.filter(d=>d.parent_id).length} subdomínios. Agendamentos são individuais.</p></div><input id="domain-search" class="search" type="search" placeholder="Buscar domínio ou subdomínio…" aria-label="Buscar domínio" value="${e(search)}"></div></div><div id="domain-results">${domainGroups()}</div>`;}
function findingView(){
  if(focusedScan)return scanFindingsView();
  const order=['critical','high','medium','low','info'];
  const groups=state.domains.map(d=>({domain:d,scan:latest(d)||d.latest_zap?.[0],items:[...hostFindings(d)].sort((a,b)=>order.indexOf(a.severity)-order.indexOf(b.severity))})).filter(g=>g.items.length).sort((a,b)=>order.indexOf(a.items[0].severity)-order.indexOf(b.items[0].severity)||a.domain.hostname.localeCompare(b.domain.hostname));
  const total=groups.reduce((sum,g)=>sum+g.items.length,0);
  const notice='<div class="notice"><span>◇</span><div><strong>Achados precisam de contexto</strong><span>Ausência de header e falha de conexão não comprovam exploração. Achados ZAP aguardam revisão humana. SQL injection só é avaliado nas execuções ativas autorizadas; abuso de login não é testado.</span></div></div>';
  const header=`<div class="panel"><div class="panel-header"><div><h2>Achados por domínio e subdomínio</h2><p>Último baseline nativo e último ZAP concluído de cada host. Expanda para consultar e revisar os achados.</p></div>${badge(total+' observações · '+groups.length+' hosts')}</div></div>`;
  if(!groups.length)return notice+header+'<div class="panel">'+empty('Nenhum achado registrado','Execute uma verificação para avaliar o domínio. Ausência de resultados não significa ausência de vulnerabilidades.')+'</div>';
  return notice+header+groups.map((g,index)=>{
    const d=g.domain,parent=state.domains.find(p=>p.id===d.parent_id);
    const counts=order.map(level=>({level,count:g.items.filter(f=>f.severity===level).length})).filter(item=>item.count);
    const open=findingGroupsOpen.has(d.id)?findingGroupsOpen.get(d.id):index===0;
    return `<details class="panel finding-group" data-finding-host="${e(d.id)}" ${open?'open':''}><summary class="finding-group-summary"><span class="domain-icon" aria-hidden="true">${d.parent_id?'↳':'◎'}</span><div class="finding-group-info"><p class="eyebrow">${d.parent_id?'SUBDOMÍNIO':'DOMÍNIO PRINCIPAL'}</p><h2>${e(d.hostname)}</h2><p>${parent?'Vinculado a '+e(parent.hostname)+' · ':''}Última varredura: ${date(g.scan.finished_at||g.scan.started_at)}</p></div><div class="finding-group-counts">${counts.map(({level,count})=>badge(severity[level]+': '+count,level)).join('')}<span class="finding-group-total">${g.items.length} ${g.items.length===1?'observação':'observações'}</span></div><span class="finding-group-arrow" aria-hidden="true">⌄</span></summary><div class="finding-list">${findingCards(g.items)}</div></details>`;
  }).join('');
}
function findingCards(items){return items.map(f=>`<article class="finding"><div class="finding-head">${badge(severity[f.severity],f.severity)}<h3>${e(f.title)}</h3>${f.source==='zap'?badge('ZAP · '+({pending:'revisão pendente',confirmed:'confirmado','false-positive':'falso positivo'}[f.review]||'revisar'),'medium'):''}</div><p>${e(f.reference)}</p><details><summary>Evidência e orientação</summary><code>${e(f.evidence)}</code><strong>Como investigar ou corrigir</strong><p>${e(f.remediation)}</p>${f.zapJob?`<p>${e(f.reviewReason||'')}</p><button class="small-btn" data-review="confirmed" data-job="${e(f.zapJob)}" data-finding="${e(f.id)}">Confirmar achado</button><button class="small-btn" data-review="false-positive" data-job="${e(f.zapJob)}" data-finding="${e(f.id)}">Registrar falso positivo</button>`:''}</details></article>`).join('');}
function scansView(){return `<div class="panel"><div class="panel-header"><div><h2>Histórico de verificações</h2><p>Baseline sem payloads de exploração · máximo de duas execuções simultâneas</p></div></div>${state.scans.length?`<div class="table-wrap"><table><thead><tr><th>DOMÍNIO</th><th>STATUS</th><th>INÍCIO</th><th>CONCLUSÃO</th><th>OBSERVAÇÕES</th></tr></thead><tbody>${state.scans.map(s=>`<tr ${resultRow(s,'native')}><td>${resultLink(s,'native')}<small>Baseline DNS + HTTPS</small></td><td>${badge(statusName[s.status]||s.status,s.status)}</td><td>${date(s.started_at)}</td><td>${date(s.finished_at)}</td><td>${s.result?.findings?.length??'—'}${s.result?.error?`<small>${e(s.result.error)}</small>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Tudo pronto para a primeira verificação','Na aba Domínios, selecione Verificar agora ou ative um agendamento.')}</div>`;}
function controlsView(){return `<div class="framework-grid"><article class="framework"><p class="eyebrow">IMPLEMENTADO</p><h2>Monitoramento de exposição</h2><ul><li>Resolução A / AAAA, MX e servidores DNS.</li><li>Presença e política de SPF e DMARC por hostname.</li><li>Validade de TLS, certificado e expiração.</li><li>Status HTTP, HSTS, CSP, MIME sniffing e enquadramento.</li><li>Atributo Secure dos cookies recebidos, sem armazenar valores.</li></ul><p>Controles pontuais referenciados no <a href="https://owasp.org/www-project-web-security-testing-guide/" target="_blank" rel="noreferrer">OWASP WSTG</a>. Não representa uma auditoria completa ou certificação.</p></article><article class="framework"><p class="eyebrow">INTEGRAÇÃO ZAP</p><h2>Análise de aplicações com ZAP</h2><p>Execute ZAP pelo painel, com fila persistente, worker isolado e importação dos achados. O baseline faz crawl limitado; o modo ativo testa SQL injection apenas nas URLs e na janela autorizadas.</p><button class="primary" data-go="zap">Abrir ZAP</button>${state.domains.map(d=>`<p><a href="/api/domains/${e(d.id)}/zap-plan">↓ Plano ZAP · ${e(d.hostname)}</a></p>`).join('')}<p>Para SQL injection: configurar caminhos, parâmetros, ambiente, limites e política ativa. Para autenticação: conta de teste, proteção contra bloqueio e validações específicas de sessão e MFA.</p></article><article class="framework"><p class="eyebrow">DISPONÍVEL</p><h2>AWS e infraestrutura</h2><p>Coleta via IAM Role de leitura, AWS Security Hub CSPM, GuardDuty, Inspector e Route 53. Avaliação de configurações pelos controles AWS e CIS disponíveis no Security Hub.</p><p>Cadastre a conta e a Role IAM de leitura na aba AWS. As fontes indisponíveis ou sem permissão são informadas por região.</p><button class="secondary" data-view="aws">Configurar AWS</button></article><article class="framework"><p class="eyebrow">DISPONÍVEL</p><h2>DNS interno e redes privadas</h2><p>Coletor dedicado na VPC ou rede corporativa, com resolvedores internos, escopo explícito e envio autenticado de evidências ao painel.</p><p>O coletor interno avalia somente hosts e CIDRs autorizados, com TLS validado. O coletor público continua separado.</p><button class="secondary" data-view="internal">Domínios internos</button></article></div>`;}
function integrationsView(){return `<div class="cards">${[['G','Google Workspace',auth.dev?'Prévia local sem SSO. Configure SAML para habilitar o acesso corporativo.':'Identidade corporativa com validação SAML de assinatura, emissor, audiência e lista de emails autorizados.',auth.dev?'Configuração pendente':'SSO configurado'],['⌁','ZAP','Worker isolado, baseline passivo e SQL injection com URLs explícitas e janela operacional.',state.zap?.ready?'Worker disponível':'Worker indisponível'],['⊞','AWS','Security Hub, GuardDuty, Inspector e Route 53 com IAM Role/STS de leitura.',state.awsConnections?.length?'Contas cadastradas':'Pronto para configurar'],['◎','DNS interno','DNS e HTTPS em CIDRs privados explícitos, por coletor corporativo ou de VPC.',state.collectors?.some(c=>c.online)?'Coletor disponível':'Configurar coletor']].map(([icon,name,description,status])=>`<article class="integration-card"><span class="integration-icon">${icon}</span><h2>${name}</h2><p>${description}</p>${badge(status,status==='SSO configurado'?'enabled':'')}</article>`).join('')}</div><div class="panel"><div class="panel-header"><h2>Configuração do acesso corporativo</h2></div><div class="coverage"><p class="muted">Domínio permitido: <strong>${e(auth.workspaceDomain)}</strong>. Cadastre as dados SAML e a lista de administradores no arquivo .env do servidor. Segredos nunca são enviados ao navegador. Consulte o README do projeto para os passos completos.</p></div></div>`;}
function auditView(){return `<div class="panel"><div class="panel-header"><h2>Ações no workspace</h2>${badge('Últimas 50 ações')}</div>${state.audit.length?`<div class="table-wrap"><table><thead><tr><th>DATA</th><th>ATOR</th><th>AÇÃO</th><th>DETALHE</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td>${date(a.at)}</td><td>${e(a.actor)}</td><td><strong>${e(a.action)}</strong></td><td>${e(a.detail)}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma ação registrada','Cadastros, execuções, alterações de agenda e logins corporativos aparecerão aqui.')}</div>`;}
function render(){const [title,description]=views[currentView];$('#breadcrumb').textContent=title;$('#page-title').textContent=title;$('#page-description').textContent=description;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===currentView));$('#content').innerHTML=({ad:adView,internal:internalView,aws:awsView,collectors:collectorsView,zap:zapView,overview,domains:domainView,findings:findingView,scans:scansView,controls:controlsView,integrations:integrationsView,audit:auditView}[currentView])();document.querySelectorAll('[data-height]').forEach(el=>el.style.height=el.dataset.height+'%');document.querySelectorAll('[data-width]').forEach(el=>el.style.width=el.dataset.width+'%');}
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.view||b.dataset.go){focusedAd=null;focusedScan=null;focusedCollection=null;currentView=b.dataset.view||b.dataset.go;search='';render();return;}try{if(b.dataset.zap){openZap(b.dataset.zap);return;}if(b.dataset.discover){b.disabled=true;await api('/api/domains/'+b.dataset.discover+'/discover',{});toast('Descoberta iniciada. Os subdomínios aparecerão automaticamente.');await refresh();}if(b.dataset.scanTree){b.disabled=true;const result=await api('/api/domains/'+b.dataset.scanTree+'/scan-tree',{});toast(result.queued.length+' varreduras adicionadas à fila; '+result.skipped.length+' já pendentes ou recentes.');await refresh();}if(b.dataset.scan){b.disabled=true;await api(`/api/domains/${b.dataset.scan}/scan`,{});toast('Verificação adicionada à fila. O resultado aparecerá automaticamente.');await refresh();}if(b.dataset.schedule){const d=state.domains.find(d=>d.id===b.dataset.schedule);await api(`/api/domains/${d.id}/schedule`,{enabled:!d.enabled,intervalHours:d.interval_hours});toast(d.enabled?'Agendamento pausado.':'Agendamento ativado; primeira execução no próximo intervalo.');await refresh();}}catch(err){b.disabled=false;toast(err.message);}});
document.addEventListener('toggle',event=>{if(event.target.matches?.('details[data-finding-host]'))findingGroupsOpen.set(event.target.dataset.findingHost,event.target.open);},true);
$('#add-domain').addEventListener('click',()=>$('#domain-dialog').showModal());
for(const id of ['close-dialog','cancel-dialog']) $('#'+id).addEventListener('click',()=>$('#domain-dialog').close());
$('#domain-form').addEventListener('submit',async event=>{event.preventDefault();const b=event.submitter;b.disabled=true;try{await api('/api/domains',{hostname:$('#hostname').value,intervalHours:Number($('#interval').value),discoverSubdomains:$('#discover-subdomains').checked});$('#domain-dialog').close();event.target.reset();toast('Domínio cadastrado. A descoberta será executada se selecionada; os agendamentos começam pausados.');currentView='domains';await refresh();}catch(err){toast(err.message);}finally{b.disabled=false;}});
$('#content').addEventListener('input',event=>{if(event.target.id==='domain-search'){search=event.target.value;$('#domain-results').innerHTML=domainGroups();}});
$('#logout').addEventListener('click',async()=>{if(auth.dev){toast('Modo local não usa sessão Google. Desative DEV_MODE para exigir SSO.');return;}await api('/api/logout',{});location.reload();});
async function boot(){try{auth=await api('/api/session');if(!auth.user){$('#login').hidden=false;$('#login-status').hidden=auth.configured;$('#login-status').textContent=auth.configured?'':'O acesso corporativo está sendo configurado. Tente novamente em instantes.';return;}$('#shell').hidden=false;$('#user-email').textContent=auth.user.email;$('#mode').textContent=auth.dev?'PRÉVIA LOCAL':'GOOGLE WORKSPACE';$('#local-notice').hidden=!auth.dev;await refresh();setInterval(()=>{if(!$('#domain-dialog').open&&!$('#zap-dialog').open&&!$('#collection-dialog').open&&!$('#ad-dialog').open&&!document.activeElement?.closest('#dashboard-filter')&&!document.activeElement?.closest('#zap-launcher'))refresh().catch(err=>toast(err.message));},10000);}catch(err){$('#login').hidden=false;$('#login-status').hidden=false;$('#login-status').textContent=err.message;}}
function zapTargets(){
  const targets=state.domains.filter(d=>d.hostname.toLowerCase().includes(zapSearch.toLowerCase().trim()));
  if(!targets.some(d=>d.id===zapSelectedId))zapSelectedId=(targets.find(d=>!d.parent_id)||targets[0])?.id||'';
  return targets;
}
function zapTargetOptions(targets){return targets.length?targets.map(d=>`<option value="${e(d.id)}" ${d.id===zapSelectedId?'selected':''}>${e(d.hostname)}</option>`).join(''):'<option value="">Nenhum host encontrado</option>';}
function zapTargetNote(targets){const target=targets.find(d=>d.id===zapSelectedId);return target?`${targets.length} ${targets.length===1?'host encontrado':'hosts encontrados'} · https://${target.hostname}/`:'Nenhum host corresponde à busca. Tente outro nome.';}
function zapView(){
  const jobs=state.zapScans||[],targets=zapTargets();
  return `<section class="panel zap-launcher"><div class="panel-header"><div><h2>Executar análise ZAP</h2><p>Busque e selecione o host exato que deseja analisar.</p></div>${badge(state.zap?.ready?'ZAP disponível':'ZAP indisponível',state.zap?.ready?'enabled':'medium')}</div><form id="zap-launcher"><div class="zap-target-fields"><label for="zap-search">Buscar alvo<input id="zap-search" type="search" autocomplete="off" placeholder="Ex.: painel, api, homologação…" value="${e(zapSearch)}"></label><label for="zap-target">Host do scan<select id="zap-target" ${targets.length?'':'disabled'}>${zapTargetOptions(targets)}</select></label><button id="zap-configure" class="primary" type="submit" ${state.zap?.ready&&targets.length?'':'disabled'}>Configurar scan →</button></div><p id="zap-target-note" class="muted">${e(zapTargetNote(targets))}</p></form><div class="zap-scope-note">Uma análise por vez, limitada ao host escolhido. Resultados exigem revisão.</div></section><section class="panel"><div class="panel-header"><div><h2>Histórico ZAP</h2><p>Clique em uma execução concluída para abrir seus achados.</p></div>${badge('Últimos 100 trabalhos')}</div>${jobs.length?`<div class="table-wrap"><table class="scan-history"><thead><tr><th>HOST / TIPO</th><th>STATUS</th><th>CRIADO / CONCLUÍDO</th><th>RESULTADO</th></tr></thead><tbody>${jobs.map(s=>`<tr ${resultRow(s,'zap')}><td>${resultLink(s,'zap')}<small>${s.mode==='sqli'?'SQL injection (ativo)':'Baseline passivo'}</small></td><td>${badge(statusName[s.status]||s.status,s.status)}${['queued','running'].includes(s.status)?`<button class="small-btn" data-zap-cancel="${e(s.id)}">Cancelar</button>`:''}</td><td>${date(s.created_at)}<small>${date(s.finished_at)}</small></td><td>${s.result?.findings?quantity(s.result.findings.length,'achado','achados')+' · '+quantity(s.result.findings.filter(f=>f.review==='pending').length,'pendente','pendentes')+' de revisão':e(s.result?.error||'Aguardando resultado')}${s.status==='completed'?'<small class="scan-result-hint">Ver achados →</small>':''}${s.mode==='sqli'?`<small>Janela: ${date(s.request.windowStart)} — ${date(s.request.windowEnd)}</small>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma análise ZAP executada','Selecione um host acima para configurar a primeira análise.')}</section>`;
}
function resultRow(scan,engine){return scan.status==='completed'?`class="scan-result-row" data-result-id="${e(scan.id)}" data-result-engine="${engine}"`:'';}
function resultLink(scan,engine){return scan.status==='completed'?`<button class="scan-result-link" data-result-id="${e(scan.id)}" data-result-engine="${engine}" aria-label="Ver achados de ${e(scan.hostname)} em ${e(date(scan.finished_at))}">${e(scan.hostname)}</button>`:`<strong>${e(scan.hostname)}</strong>`;}
function openScanResult(engine,id){
  const scan=(engine==='zap'?state.zapScans:state.scans)?.find(s=>s.id===id);
  if(!scan||scan.status!=='completed')return;
  focusedScan={engine,id,scan};currentView='findings';render();window.scrollTo({top:0,behavior:'instant'});
  const heading=$('#page-title');heading.tabIndex=-1;heading.focus({preventScroll:true});
}
function scanFindingsView(){
  const scan=(focusedScan.engine==='zap'?state.zapScans:state.scans)?.find(s=>s.id===focusedScan.id)||focusedScan.scan;
  focusedScan.scan=scan;
  const engine=focusedScan.engine==='zap'?(scan.mode==='sqli'?'ZAP · SQL injection':'ZAP · Baseline passivo'):'Baseline DNS + HTTPS';
  const items=(scan.result?.findings||[]).map(f=>focusedScan.engine==='zap'?{...f,zapJob:scan.id}:f);
  const levels=['critical','high','medium','low','info'];items.sort((a,b)=>levels.indexOf(a.severity)-levels.indexOf(b.severity));
  return `<div class="panel scan-result-header"><div><p class="eyebrow">ACHADOS DA EXECUÇÃO SELECIONADA</p><h2>${e(scan.hostname)}</h2><p>${e(engine)} · Concluída em ${date(scan.finished_at)}</p><div class="scan-result-counts">${levels.filter(level=>items.some(f=>f.severity===level)).map(level=>badge(severity[level]+': '+items.filter(f=>f.severity===level).length,level)).join('')}${badge(quantity(items.length,'achado','achados'))}</div></div><div class="scan-result-actions"><button class="secondary" data-view="${focusedScan.engine==='zap'?'zap':'scans'}">← Voltar ao histórico</button><button class="text-action" data-view="findings">Todos os achados</button></div></div><div class="panel">${items.length?`<div class="finding-list">${findingCards(items)}</div>`:empty('Nenhum achado nesta execução','O scan foi concluído sem alertas. Isso não comprova ausência de vulnerabilidades.')}</div>`;
}

let zapHost;
document.addEventListener('click',event=>{
  const target=event.target.closest('[data-result-id]');
  if(target&&!event.target.closest('[data-zap-cancel]'))openScanResult(target.dataset.resultEngine,target.dataset.resultId);
});
$('#content').addEventListener('input',event=>{
  if(event.target.id!=='zap-search')return;
  zapSearch=event.target.value;const targets=zapTargets();
  $('#zap-target').innerHTML=zapTargetOptions(targets);$('#zap-target').disabled=!targets.length;
  $('#zap-configure').disabled=!state.zap?.ready||!targets.length;
  $('#zap-target-note').textContent=zapTargetNote(targets);
});
$('#content').addEventListener('change',event=>{
  if(event.target.id==='zap-target'){zapSelectedId=event.target.value;$('#zap-target-note').textContent=zapTargetNote(zapTargets());}
});
$('#content').addEventListener('submit',event=>{
  if(event.target.id!=='zap-launcher')return;
  event.preventDefault();if(state.zap?.ready&&zapSelectedId)openZap(zapSelectedId);
});
document.addEventListener('click',async event=>{
  const cancel=event.target.closest('button[data-zap-cancel]');
  if(cancel){try{await api('/api/zap/'+cancel.dataset.zapCancel+'/cancel',{});toast('Cancelamento solicitado.');await refresh();}catch(error){toast(error.message);}return;}
  const button=event.target.closest('button[data-review]');if(!button)return;
  const reason=button.dataset.review==='false-positive'?prompt('Motivo do falso positivo (até 500 caracteres):'):'';
  if(reason===null)return;
  try{await api('/api/zap/'+button.dataset.job+'/review',{findingId:button.dataset.finding,status:button.dataset.review,reason});toast('Revisão registrada.');await refresh();}catch(error){toast(error.message);}
});
const localInput=d=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);
function openZap(id){
  zapHost=state.domains.find(d=>d.id===id);if(!zapHost)return;
  $('#zap-title').textContent='ZAP · '+zapHost.hostname;
  $('#zap-form').reset();$('#zap-active').hidden=true;
  $('#zap-start').value=localInput(new Date());$('#zap-end').value=localInput(new Date(Date.now()+3600000));
  $('#zap-dialog').showModal();
}
$('#zap-mode').addEventListener('change',()=>{$('#zap-active').hidden=$('#zap-mode').value!=='sqli';});
for(const id of ['close-zap','cancel-zap'])$('#'+id).addEventListener('click',()=>$('#zap-dialog').close());
$('#zap-form').addEventListener('submit',async event=>{
  event.preventDefault();const button=event.submitter;button.disabled=true;
  try{
    const mode=$('#zap-mode').value;
    const input={mode};
    if(mode==='sqli')Object.assign(input,{targets:$('#zap-targets').value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean),authorized:$('#zap-authorized').checked,windowStart:$('#zap-start').value?new Date($('#zap-start').value).toISOString():null,windowEnd:$('#zap-end').value?new Date($('#zap-end').value).toISOString():null});
    await api('/api/domains/'+zapHost.id+'/zap',input);
    $('#zap-dialog').close();currentView='zap';toast('Trabalho ZAP adicionado à fila.');await refresh();
  }catch(error){toast(error.message);}finally{button.disabled=false;}
});
const collectorOptions=()=> (state.collectors||[]).filter(c=>c.enabled).map(c=>`<option value="${e(c.id)}">${e(c.name)} · ${c.online?'online':'offline'}</option>`).join('');
const collectionBusy=job=>['queued','running'].includes(job?.status);
function collectionActions(asset,kind){
  const collector=state.collectors?.find(c=>c.id===asset.collector_id),busy=collectionBusy(asset.latest);
  const awsReady=kind!=='aws'||collector?.capabilities.aws?.roleArns?.includes(asset.settings.roleArn)&&collector?.capabilities.aws?.sourceProfiles?.includes(asset.settings.sourceProfile)&&asset.settings.regions.every(r=>collector?.capabilities.aws?.regions?.includes(r));
  return `<button class="small-btn" data-collect-kind="${kind}" data-collect-id="${e(asset.id)}" ${collector?.online&&!busy&&awsReady?'':'disabled'} title="${awsReady?'Executar coleta':'Autorize a Role e o perfil na política do coletor antes de coletar.'}">${busy?statusName[asset.latest.status]:kind==='aws'?'Coletar':'Verificar'}</button><button class="small-btn" data-collection-schedule="${kind}" data-target="${e(asset.id)}" ${!awsReady&&!asset.enabled?'disabled':''}>${asset.enabled?'Pausar agenda':'Agendar'}</button>${asset.latest&&!busy?`<button class="small-btn" data-collection-result="${e(asset.latest.id)}">Ver resultado</button>`:''}`;
}
function collectionHistory(kind){
  const jobs=(state.collectionJobs||[]).filter(j=>j.kind===kind);
  if(!jobs.length)return '';
  const label=j=>(kind==='internal'?state.internalAssets:state.awsConnections)?.find(a=>a.id===j.target_id)?.[kind==='internal'?'hostname':'name']||'Ativo removido';
  return `<section class="panel"><div class="panel-header"><h2>Histórico de ${kind==='aws'?'coletas AWS':'verificações internas'}</h2></div><div class="table-wrap"><table><thead><tr><th>ALVO</th><th>STATUS</th><th>INÍCIO / CONCLUSÃO</th><th>RESULTADO</th></tr></thead><tbody>${jobs.map(j=>`<tr><td>${collectionBusy(j)?e(label(j)):`<button class="scan-result-link" data-collection-result="${e(j.id)}">${e(label(j))}</button>`}</td><td>${badge(statusName[j.status]||j.status,j.status)}${collectionBusy(j)?`<button class="small-btn" data-collection-cancel="${e(j.id)}">Cancelar</button>`:''}</td><td>${date(j.started_at||j.created_at)}<small>${date(j.finished_at)}</small></td><td>${j.result?.findingCount===undefined?'—':quantity(j.result.findingCount,'achado','achados')}${j.result?.error?`<small>${e(j.result.error)}</small>`:''}</td></tr>`).join('')}</tbody></table></div></section>`;
}
function internalView(){
  if(focusedCollection?.kind==='internal')return collectionResultView();
  const assets=state.internalAssets||[],collectors=(state.collectors||[]).filter(c=>c.enabled);
  return `<section class="panel"><div class="panel-header"><div><h2>Hosts da rede interna</h2><p>DNS, TLS e HTTPS no coletor escolhido. Agendamentos começam pausados.</p></div><button class="primary" data-collection-form="internal" ${collectors.length?'':'disabled'}>+ Adicionar host</button></div>${!collectors.length?empty('Conecte um coletor para começar','Cadastre um coletor e instale-o na rede autorizada. Nenhum endereço privado é liberado no scanner público.') :assets.length?`<div class="table-wrap"><table><thead><tr><th>HOST</th><th>COLETOR / DNS</th><th>ÚLTIMA EXECUÇÃO</th><th>ACHADOS</th><th>AÇÕES</th></tr></thead><tbody>${assets.map(a=>`<tr><td><strong>${e(a.hostname)}</strong><small>${a.enabled?'Agenda ativa':'Agenda pausada'} · ${a.interval_hours}h</small></td><td>${e(a.collector_name)}<small>${e([...(a.latest?.result?.dns?.a?.records||[]),...(a.latest?.result?.dns?.aaaa?.records||[])].join(', ')||'DNS ainda não consultado')}</small></td><td>${badge(statusName[a.latest?.status]||'Não verificado',a.latest?.status||'')}<small>${date(a.latest?.finished_at)}</small></td><td>${a.latest?.result?.findingCount??'—'}${a.latest?.result?.error?`<small>${e(a.latest.result.error)}</small>`:''}</td><td>${collectionActions(a,'internal')}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum host interno cadastrado','Adicione nomes DNS dentro dos sufixos e CIDRs autorizados no coletor.')}</section>${collectionHistory('internal')}`;
}
function awsView(){
  if(focusedCollection?.kind==='aws')return collectionResultView();
  const connections=state.awsConnections||[],collectors=(state.collectors||[]).filter(c=>c.enabled);
  return `<section class="panel"><div class="panel-header"><div><h2>Contas AWS</h2><p>Security Hub, GuardDuty, Inspector e Route 53/Resolver. A coleta usa IAM Role/STS de leitura.</p></div><button class="primary" data-collection-form="aws" ${collectors.length?'':'disabled'}>+ Configurar conta</button></div><div class="cloud-setup-note"><strong>Configuração IAM</strong><p>Crie a Role com a política de leitura, configure o perfil e autorize o ARN na política do coletor. Cadastre abaixo o Account ID, ARN da Role e regiões. As credenciais temporárias ficam no coletor; access keys não são recebidas pelo painel.</p><a class="secondary" href="/api/aws/iam-policy">↓ Baixar política IAM de leitura</a><button class="text-action" data-view="collectors">Ver coletores →</button></div>${!collectors.length?empty('Conecte um coletor','O coletor pode ficar no servidor corporativo ou em uma VPC com acesso aos serviços AWS.'):connections.length?`<div class="table-wrap"><table><thead><tr><th>CONTA / REGIÕES</th><th>COLETOR</th><th>ÚLTIMA COLETA</th><th>AÇÕES</th></tr></thead><tbody>${connections.map(a=>`<tr><td><strong>${e(a.name)}</strong><small>${e(a.account_id)} · ${e(a.settings.regions.join(', '))}</small><small>${e(a.settings.roleArn)}</small></td><td>${e(a.collector_name)}<small>Perfil: ${e(a.settings.sourceProfile)}</small></td><td>${badge(statusName[a.latest?.status]||'Aguardando configuração IAM',a.latest?.status||'')}<small>${date(a.latest?.finished_at)}</small>${a.latest?.result?.error?`<small>${e(a.latest.result.error)}</small>`:''}</td><td>${collectionActions(a,'aws')}</td></tr>`).join('')}</tbody></table></div>`:empty('Pronto para configurar a primeira conta','Cadastre a conexão quando a Role IAM de leitura estiver disponível. Nenhum serviço AWS é ativado por esta integração.')}</section>${collectionHistory('aws')}`;
}
function collectorsView(){
  const collectors=state.collectors||[];
  return `<section class="panel"><div class="panel-header"><div><h2>Coletores corporativos e de VPC</h2><p>O escopo é anunciado pelo coletor e validado novamente antes de cada execução.</p></div><button class="primary" data-collection-form="collector">+ Registrar coletor</button></div>${collectors.length?collectors.map(c=>`<article class="collector-item"><div><h3>${e(c.name)} ${badge(!c.enabled?'Revogado':c.online?'Online':'Offline',c.online?'enabled':'')}</h3><p>${c.zone==='vpc'?'VPC':'Rede corporativa'} · Último contato: ${date(c.last_seen)}</p><dl><dt>Sufixos internos</dt><dd>${e(c.capabilities.internal?.suffixes?.join(', ')||'Não configurados')}</dd><dt>CIDRs autorizados</dt><dd>${e(c.capabilities.internal?.cidrs?.join(', ')||'Não configurados')}</dd><dt>DNS</dt><dd>${e(c.capabilities.internal?.dnsServers?.join(', ')||'Não configurado')}</dd><dt>Regiões AWS</dt><dd>${e(c.capabilities.aws?.regions?.join(', ')||'Não configuradas')}</dd><dt>Roles AWS autorizadas</dt><dd>${e(c.capabilities.aws?.roleArns?.join(', ')||'Aguardando configuração IAM')}</dd></dl></div>${c.enabled?`<button class="small-btn" data-collector-revoke="${e(c.id)}">Revogar acesso</button>`:''}</article>`).join(''):empty('Nenhum coletor conectado','Registre o coletor e use o token uma única vez na instalação do serviço. Não envie tokens pelo chat.')}</section>`;
}
function collectionResultView(){
  const j=focusedCollection,asset=(j.kind==='aws'?state.awsConnections:state.internalAssets)?.find(a=>a.id===j.target_id),name=asset?.hostname||asset?.name||'Resultado da coleta',result=j.result||{};
  const items=(result.findings||[]).map(f=>({...f,evidence:f.evidence+(f.resource?'\nRecurso: '+f.resource:'')+(f.region?'\nRegião: '+f.region:'')}));
  return `<section class="panel scan-result-header"><div><p class="eyebrow">RESULTADO DA EXECUÇÃO SELECIONADA</p><h2>${e(name)}</h2><p>${badge(statusName[j.status]||j.status,j.status)} · ${date(j.finished_at)}</p></div><button class="secondary" data-view="${j.kind==='aws'?'aws':'internal'}">← Voltar ao histórico</button></section>${result.error?`<div class="notice"><strong>${e(result.error)}</strong></div>`:''}${result.limited?'<div class="notice">A coleta atingiu o limite de resultados. O relatório é parcial e não representa todo o inventário.</div>':''}${result.sources?.length?`<section class="panel"><div class="panel-header"><h2>Cobertura por fonte e região</h2></div><div class="table-wrap"><table><thead><tr><th>FONTE</th><th>REGIÃO</th><th>ESTADO</th><th>RESULTADOS</th></tr></thead><tbody>${result.sources.map(s=>`<tr><td>${e(s.source)}</td><td>${e(s.region)}</td><td>${badge(({ok:'Coletado',error:'Falhou',not_enabled:'Não habilitado'})[s.status]||s.status,s.status==='ok'?'enabled':'medium')}<small>${e(s.error||'')}${s.limited?' · Limitado':''}</small></td><td>${s.count}</td></tr>`).join('')}</tbody></table></div></section>`:''}<section class="panel"><div class="panel-header"><h2>Achados desta execução</h2>${badge(quantity(items.length,'achado','achados'))}</div>${items.length?`<div class="finding-list">${findingCards(items)}</div>`:empty('Nenhum achado disponível',j.status==='completed'?'Nenhum alerta foi retornado nesta coleta. Isso não comprova ausência de vulnerabilidades.':'A coleta não avaliou todas as fontes. Confira o estado e os erros apresentados.')}</section>${result.assets?.length?`<section class="panel"><div class="panel-header"><h2>Inventário DNS AWS</h2><p>Os nomes encontrados não são escaneados automaticamente.</p></div><div class="table-wrap"><table><thead><tr><th>NOME</th><th>TIPO / ESCOPO</th><th>REGIÃO</th></tr></thead><tbody>${result.assets.map(a=>`<tr><td>${e(a.name)}<small>${e(a.id)}</small></td><td>${a.type==='dns-zone'?(a.private?'Zona privada':'Zona pública'):e(a.direction||'Resolver')}<small>${e(a.status||'')}</small></td><td>${e(a.region)}</td></tr>`).join('')}</tbody></table></div></section>`:''}`;
}
function openCollectionDialog(type){
  collectionDialogType=type;const options=collectorOptions();
  const title=({internal:'Adicionar host interno',aws:'Configurar conta AWS',collector:'Registrar coletor'})[type];
  const fields=type==='collector'?'<label>Nome<input name="name" required maxlength="80" placeholder="Coletor corporativo"></label><label>Zona<select name="zone"><option value="corporate">Rede corporativa</option><option value="vpc">VPC</option></select></label>':`<label>Coletor<select name="collectorId" required>${options}</select></label>`+(type==='internal'?'<label>Hostname interno<input name="hostname" required placeholder="app.casaeterra.com" maxlength="253"></label><p>A resolução usará o DNS anunciado pelo coletor. Somente HTTPS na porta 443, com certificado validado.</p>':'<label>Nome da conexão<input name="name" required value="Casa & Terra" maxlength="80"></label><label>Account ID (12 dígitos)<input name="accountId" required pattern="[0-9]{12}" inputmode="numeric" maxlength="12"></label><label>ARN da Role IAM de leitura<input name="roleArn" required placeholder="arn:aws:iam::123456789012:role/SecHubReadOnly"></label><label>Perfil de origem no coletor<input name="sourceProfile" required value="sechub-source"></label><label>External ID (se exigido na trust policy)<input name="externalId" maxlength="128"></label><label>Regiões (separadas por vírgula)<input name="regions" required value="us-east-1, sa-east-1"></label><p>O perfil de origem deve usar SSO, IAM Role ou credential_process. Não cadastre access keys no painel. A conexão é salva com a agenda pausada.</p>');
  $('#collection-form').innerHTML=`<div class="dialog-heading"><h2>${title}</h2><button type="button" class="icon-button" data-close-collection aria-label="Fechar">×</button></div>${fields}<div class="dialog-actions"><button class="secondary" type="button" data-close-collection>Cancelar</button><button class="primary" type="submit">Salvar</button></div>`;
  $('#collection-dialog').showModal();
}
document.addEventListener('click',async event=>{
  const button=event.target.closest('button');if(!button)return;
  if(button.hasAttribute('data-close-collection')){$('#collection-dialog').close();$('#collection-form').innerHTML='';return;}
  try{
    if(button.dataset.collectionForm){openCollectionDialog(button.dataset.collectionForm);return;}
    if(button.dataset.collectId){button.disabled=true;await api(`/api/${button.dataset.collectKind==='aws'?'aws/connections':'internal/assets'}/${button.dataset.collectId}/scan`,{});toast('Coleta adicionada à fila.');await refresh();}
    if(button.dataset.collectionSchedule){const kind=button.dataset.collectionSchedule,asset=(kind==='aws'?state.awsConnections:state.internalAssets).find(a=>a.id===button.dataset.target);await api(`/api/${kind==='aws'?'aws/connections':'internal/assets'}/${asset.id}/schedule`,{enabled:!asset.enabled,intervalHours:asset.interval_hours});await refresh();}
    if(button.dataset.collectionResult){const job=await api('/api/collection-jobs/'+button.dataset.collectionResult);focusedCollection=job;focusedScan=null;currentView=job.kind==='aws'?'aws':'internal';render();window.scrollTo({top:0,behavior:'instant'});}
    if(button.dataset.collectionCancel){await api('/api/collection-jobs/'+button.dataset.collectionCancel+'/cancel',{});await refresh();}
    if(button.dataset.collectorRevoke&&confirm('Revogar o acesso deste coletor? Os próximos trabalhos e contatos serão bloqueados.')){await api('/api/collectors/'+button.dataset.collectorRevoke+'/revoke',{});await refresh();}
  }catch(error){button.disabled=false;toast(error.message);}
});
$('#collection-form').addEventListener('submit',async event=>{
  event.preventDefault();const button=event.submitter;button.disabled=true;
  try{
    const data=Object.fromEntries(new FormData(event.target));
    if(collectionDialogType==='aws')data.regions=data.regions.split(',').map(s=>s.trim()).filter(Boolean);
    const route=({internal:'/api/internal/assets',aws:'/api/aws/connections',collector:'/api/collectors'})[collectionDialogType];
    const result=await api(route,data);
    if(collectionDialogType==='collector'){
      $('#collection-form').innerHTML=`<h2>Token do coletor</h2><p>Copie para COLLECTOR_TOKEN no arquivo de ambiente do serviço. Este token não será exibido novamente. Não o envie pelo chat.</p><textarea readonly rows="3">${e(result.token)}</textarea><div class="dialog-actions"><button type="button" class="primary" data-close-collection>Fechar</button></div>`;
    }else{$('#collection-dialog').close();currentView=collectionDialogType==='aws'?'aws':'internal';toast('Configuração salva com a agenda pausada.');}
    await refresh();
  }catch(error){button.disabled=false;toast(error.message);}
});
$('#collection-dialog').addEventListener('close',()=>{$('#collection-form').innerHTML='';});

let focusedAd=null;
const adState={credentials_pending:'Aguardando credenciais',ok:'Coletando',error:'Falha na coleta'};
const adError={CREDENTIALS_PENDING:'Preencha a conta de serviço no arquivo protegido.',CONFIG_INVALID:'Verifique o formato e as permissões do arquivo de configuração.',AUTH_FAILED:'Credencial recusada. As tentativas estão pausadas até alterar o arquivo.',ACCESS_DENIED:'A conta precisa de leitura do Security e acesso ao endpoint WinRM.',WINRM_UNAVAILABLE:'Verifique rede, WinRM e permissões da sessão remota.',EVENT_QUERY_FAILED:'O Windows recusou a consulta de eventos.',INVALID_RESPONSE:'Resposta de eventos inválida.',LOG_RESET:'O log foi reiniciado. A coleta retomou pela janela inicial.',LOG_GAP:'Parte do log expirou antes da leitura.'};
function adEventTable(events){return events.length?`<div class="table-wrap"><table><thead><tr><th>HORÁRIO / EVENTO</th><th>CONTA</th><th>ORIGEM</th><th>RESULTADO</th></tr></thead><tbody>${events.map(v=>`<tr><td>${date(v.time)}<small>Evento ${Number(v.eventId)} · registro ${Number(v.recordId)}</small></td><td>${e(v.domain?v.domain+'\\'+v.user:v.user||v.actor||'—')}<small>${e(v.member||v.group||'')}</small></td><td>${e(v.ip||v.workstation||'Não informada')}<small>${e(v.computer)}</small></td><td>${badge(({success:'Aceita',failure:'Recusada',activity:'Atividade'})[v.outcome]||'Atividade',v.outcome==='failure'?'medium':'')}<small>${e(v.status)}${v.logonType?' · Tipo '+e(v.logonType):''}</small></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum evento recebido','Confira as credenciais, as permissões e a auditoria do Windows. A ausência de eventos não comprova ausência de atividade.');}
function adView(){
  const a=state.ad||{sources:[],events:[],alerts:[],counts:{events:0,openAlerts:0}};
  if(focusedAd){const v=focusedAd;return `<section class="panel scan-result-header"><div><p class="eyebrow">ALERTA DO ACTIVE DIRECTORY</p><h2>${e(v.title)}</h2><p>${badge(severity[v.severity],v.severity)} · ${date(v.created_at)} · ${e(v.account||v.origin)}</p></div><button class="secondary" data-view="ad">← Voltar aos alertas</button></section><div class="notice">Este alerta indica comportamento que precisa de revisão. Não comprova comprometimento da conta.</div><section class="panel"><div class="panel-header"><h2>Evidências correlacionadas</h2><button class="primary" data-ad-review="${e(v.id)}">Revisar alerta</button></div>${adEventTable(v.evidence)}<div class="cloud-setup-note">${e(({pending:'Pendente de revisão',confirmed:'Confirmado', 'false-positive':'Falso positivo'})[v.status])}${v.review_reason?` · ${e(v.review_reason)} · ${e(v.reviewed_by)}`:''}</div></section>`;}
  return `<section class="panel"><div class="panel-header"><div><h2>Autenticação do Active Directory</h2><p>${a.counts.events} eventos retidos · ${a.counts.openAlerts} alertas pendentes</p></div><button class="secondary" data-ad-rules>Configurar regras</button></div>${a.sources.length?a.sources.map(s=>`<div class="collector-item"><div><h3>${e(s.name)} · ${e(s.controller)} ${badge(s.online?(adState[s.status]||s.status):'Coletor offline',s.online&&s.status==='ok'?'enabled':'medium')}</h3><p>Contato: ${date(s.last_seen)} · Última leitura do Windows: ${date(s.last_success)}</p><p>${e(adError[s.error]||'')}${s.backlog?' Há eventos aguardando processamento.':''}</p></div></div>`).join(''):empty('Instale o coletor AD','Consulte docs/ACTIVE-DIRECTORY.md para instalação e delegação de leitura.')}</section><section class="panel"><div class="panel-header"><h2>Alertas de comportamento</h2>${badge('Últimos 100')}</div>${a.alerts.length?`<div class="table-wrap"><table><thead><tr><th>ALERTA</th><th>CONTA / ORIGEM</th><th>HORÁRIO</th><th>REVISÃO</th></tr></thead><tbody>${a.alerts.map(v=>`<tr><td><button class="scan-result-link" data-ad-alert="${e(v.id)}">${e(v.title)}</button><small>${badge(severity[v.severity],v.severity)}</small></td><td>${e(v.account||'Várias contas')}<small>${e(v.origin)}</small></td><td>${date(v.created_at)}</td><td>${badge(({pending:'Pendente',confirmed:'Confirmado','false-positive':'Falso positivo'})[v.status])}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum alerta disponível','As regras serão aplicadas aos eventos recebidos. As configurações de horário e contas específicas são opcionais.')}</section><section class="panel"><div class="panel-header"><h2>Eventos recentes</h2>${badge('Últimos 100')}</div>${adEventTable(a.events)}</section>`;
}
document.addEventListener('click',async event=>{
  const b=event.target.closest('button');if(!b)return;
  if(b.hasAttribute('data-ad-close')){$('#ad-dialog').close();return;}
  try{
    if(b.dataset.adAlert){focusedAd=await api('/api/ad/alerts/'+b.dataset.adAlert);render();window.scrollTo({top:0,behavior:'instant'});}
    if(b.hasAttribute('data-ad-rules')){
      const r=state.ad.rules;
      $('#ad-form').innerHTML=`<div class="dialog-heading"><h2>Regras do Active Directory</h2><button type="button" class="icon-button" data-ad-close aria-label="Fechar">×</button></div><p>As regras geram alertas revisáveis. Nenhuma conta é bloqueada automaticamente.</p>${[['failureThreshold','Falhas por conta',3,100],['sprayThreshold','Contas recusadas por origem',3,100],['windowMinutes','Janela de correlação (minutos)',1,60],['startHour','Início do horário útil',0,23],['endHour','Fim do horário útil',1,24]].map(([key,label,min,max])=>`<label>${label}<input type="number" name="${key}" min="${min}" max="${max}" value="${r[key]}" required></label>`).join('')}<label>Fuso horário<input name="timeZone" value="${e(r.timeZone)}" required></label><label><input type="checkbox" name="offHours" ${r.offHours?'checked':''}> Alertar login interativo fora do horário</label>${[['ignoredAccounts','Contas ignoradas'],['privilegedAccounts','Contas privilegiadas monitoradas'],['serviceAccounts','Contas de serviço (alertar login interativo)']].map(([key,label])=>`<label>${label}<textarea name="${key}" rows="2" placeholder="DOMINIO\\usuario, outra_conta">${e(r[key].join(', '))}</textarea></label>`).join('')}<div class="dialog-actions"><button class="secondary" type="button" data-ad-close>Cancelar</button><button class="primary" type="submit">Salvar regras</button></div>`;$('#ad-form').dataset.kind='rules';$('#ad-dialog').showModal();
    }
    if(b.dataset.adReview){$('#ad-form').dataset.kind='review';$('#ad-form').dataset.alert=b.dataset.adReview;$('#ad-form').innerHTML=`<div class="dialog-heading"><h2>Revisar alerta</h2><button type="button" class="icon-button" data-ad-close aria-label="Fechar">×</button></div><label>Classificação<select name="status"><option value="confirmed">Confirmado</option><option value="false-positive">Falso positivo</option><option value="pending">Pendente</option></select></label><label>Justificativa<textarea name="reason" required maxlength="1000" rows="4"></textarea></label><div class="dialog-actions"><button class="secondary" type="button" data-ad-close>Cancelar</button><button class="primary" type="submit">Salvar revisão</button></div>`;$('#ad-dialog').showModal();}
  }catch(err){toast(err.message);}
});
$('#ad-form').addEventListener('submit',async event=>{
  event.preventDefault();const b=event.submitter;b.disabled=true;
  try{const form=event.target,data=Object.fromEntries(new FormData(form));
    if(form.dataset.kind==='rules'){for(const k of ['failureThreshold','sprayThreshold','windowMinutes','startHour','endHour'])data[k]=Number(data[k]);data.offHours=form.elements.offHours.checked;for(const k of ['ignoredAccounts','privilegedAccounts','serviceAccounts'])data[k]=data[k].split(/[,\n]/).map(v=>v.trim()).filter(Boolean);await api('/api/ad/rules',data);}
    else{await api('/api/ad/alerts/'+form.dataset.alert+'/review',data);focusedAd=await api('/api/ad/alerts/'+form.dataset.alert);}
    $('#ad-dialog').close();toast('Configuração salva.');await refresh();render();
  }catch(err){toast(err.message);}finally{b.disabled=false;}
});
$('#ad-dialog').addEventListener('close',()=>{$('#ad-form').innerHTML='';});
document.addEventListener('change',event=>{if(event.target.id==='dashboard-days'){const custom=event.target.value==='custom',form=event.target.form;form.elements.start.disabled=!custom;form.elements.end.disabled=!custom;}});
document.addEventListener('submit',async event=>{
  if(event.target.id!=='dashboard-filter')return;
  event.preventDefault();const button=event.submitter;button.disabled=true;
  try{const value=Object.fromEntries(new FormData(event.target)),filter=value.days==='custom'?{start:value.start,end:value.end,accounts:value.accounts}:{days:value.days,accounts:value.accounts};await refresh(filter);render();}
  catch(error){toast(error.message);}finally{button.disabled=false;}
});
boot();
